// Добавляет температурные режимы применения в "detail" там, где препарат
// упомянут для обработки почвы/растений (не посадочного материала - там
// температура воздуха не важна, поэтому семена/клубни/луковицы перед
// посадкой не трогаем).
//
// Источники (веб-поиск, август 2026), диапазоны как в инструкциях
// производителей/агро-справочников:
// - ХОМ (хлорокись меди): не выше +30°C (выше - ожог листвы) -
//   ogorod.ru/wiki/fungicides/14802, stop-pest.ru/hom-instrukcija
// - Бордоская жидкость 3%/1%: +5…+25°C оптимально -
//   ogorod.ru/wiki/fungicides/16065
// - Абига-Пик: +5…+25°C (эффективность падает выше +25°C) -
//   ogorod.ru/wiki/fungicides/14226
// - Актара (тиаметоксам): +10…+29°C, оптимально +12…+25°C -
//   grow.in.ua/blog/technology/aktara-instrukciya-po-primeneniyu
// - Фитоверм: действует от +12°C, оптимально от +18°C и выше (эффективность
//   растёт с температурой) - ogorod.ru/wiki/insecticides/14768
// - Топаз (пенконазол): от +10°C, оптимум +10…+25°C -
//   sadovniki.org/topaz-instrukcija-primenenija
// - Скор (дифеноконазол): оптимум +14…+25°C, ниже +12°C эффект резко
//   падает - pochva.net/industrial/skor.html
// - Битоксибациллин: действует от +13°C, оптимум +18…+32°C -
//   darvin-market.ru (Битоксибациллин инструкция)
// - Лепидоцид: малоэффективен ниже +13°C, оптимум +18…+30°C -
//   masterasada.ru/life/instructions/lepidocid
// - Тиовит Джет/коллоидная сера: оптимум +20…+28°C, выше +30°C - ожоги
//   листьев - syngenta.ru/lawn-and-garden (Тиовит Джет)
// - Ридомил Голд: не выше +28°C (ожоги, особенно у молодых растений) -
//   agrohimka.ru/blog/ridomil-gold-instruktsiya
// Ракурс (+10°C), Пиноцид (+10°C), Хорус (+3°C) уже были в данных с
// температурой - не трогаем. Для Инта-Вира, Клипера, Землина, Актеллика,
// Превикура, Триходермина чёткого температурного порога в источниках не
// нашлось - температуру для них не придумываем, оставляем как есть.

const path = require('path');
const XLSX = require('xlsx');

const XLSX_PATH = path.resolve(__dirname, '..', '..', 'garden-data.xlsx');
const wb = XLSX.readFile(XLSX_PATH);
const rows = XLSX.utils.sheet_to_json(wb.Sheets['Calendar']);

// [искомый фрагмент, замена] - применяется как обычный replace ко всем
// detail, где фрагмент встречается (один и тот же фрагмент часто
// дублируется в нескольких записях/регионах - чинит все разом).
const REPLACEMENTS = [
  // ХОМ + 1%-я бордоская жидкость (розы/декоративные, 4 идентичные записи)
  [
    '(ХОМ, 1%-я бордоская жидкость)',
    '(ХОМ — не выше +30°C, 1%-я бордоская жидкость — +5…+25°C)',
  ],
  // Шютте на туе/можжевельнике/самшите
  [
    'ХОМ (хлорокись меди, 40 г на 10 л воды) или 1%-я бордоская жидкость, опрыскивание по кроне в сухую погоду.',
    'ХОМ (хлорокись меди, 40 г на 10 л воды, не выше +30°C) или 1%-я бордоская жидкость (+5…+25°C), опрыскивание по кроне в сухую погоду.',
  ],
  // Хлорокись меди (ХОМ) в июле, помидор/картофель/капуста
  [
    'хлорокиси меди (ХОМ) — строго с соблюдением срока ожидания',
    'хлорокиси меди (ХОМ, не выше +30°C) — строго с соблюдением срока ожидания',
  ],
  // Побурение хвои (июль)
  [
    'повторная обработка ХОМ или «Абига-Пик» по инструкции.',
    'повторная обработка ХОМ (не выше +30°C) или «Абига-Пик» (+5…+25°C) по инструкции.',
  ],
  // Последняя обработка от фитофторы (август)
  [
    'Последняя обработка от фитофторы — ХОМ или «Абига-Пик» (медьсодержащие, срок ожидания до сбора — 20 дней).',
    'Последняя обработка от фитофторы — ХОМ (не выше +30°C) или «Абига-Пик» (+5…+25°C, медьсодержащие, срок ожидания до сбора — 20 дней).',
  ],
  // Искореняющая обработка сентябрь (бордо + ХОМ по кроне и листьям)
  [
    '3%-я бордоская жидкость (300 г медного купороса + 400 г извести на 10 л воды) или ХОМ (40 г на 10 л) по кроне и опавшим листьям, в сухую безветренную погоду.',
    '3%-я бордоская жидкость (+5…+25°C, 300 г медного купороса + 400 г извести на 10 л воды) или ХОМ (не выше +30°C, 40 г на 10 л) по кроне и опавшим листьям, в сухую безветренную погоду.',
  ],
  // Шютте хвойных сентябрь/октябрь/ноябрь - три идентичные строки, чинятся разом
  [
    'ХОМ (40 г на 10 л воды) или «Абига-Пик» по кроне хвойных',
    'ХОМ (40 г на 10 л воды, не выше +30°C) или «Абига-Пик» (+5…+25°C) по кроне хвойных',
  ],
  [
    'ХОМ (40 г на 10 л воды) или «Абига-Пик» по кроне в сухую погоду',
    'ХОМ (40 г на 10 л воды, не выше +30°C) или «Абига-Пик» (+5…+25°C) по кроне в сухую погоду',
  ],
  // Виноград: милдью/оидиум
  [
    'От милдью — контактный «ХОМ» или системный «Ридомил Голд» до цветения.',
    'От милдью — контактный «ХОМ» (не выше +30°C) или системный «Ридомил Голд» (не выше +28°C) до цветения.',
  ],
  [
    'не совмещать с маслосодержащими средствами и не применять в жару выше +30°C — риск ожога листьев.',
    'оптимально при +20…+28°C, не совмещать с маслосодержащими средствами и не применять в жару выше +30°C — риск ожога листьев.',
  ],

  // Актара
  [
    'Актара (тиаметоксам, системного действия, защита 3-4 недели)',
    'Актара (тиаметоксам, системного действия, защита 3-4 недели; работает при +10…+29°C, оптимально +12…+25°C)',
  ],
  [
    '«Актара» (тиаметоксам, системного действия); при слабом поражении',
    '«Актара» (тиаметоксам, системного действия; +10…+29°C, оптимально +12…+25°C); при слабом поражении',
  ],
  [
    '«Инта-Вир» или «Актара» при обнаружении гусениц/личинок',
    '«Инта-Вир» или «Актара» (+10…+29°C) при обнаружении гусениц/личинок',
  ],

  // Фитоверм (несколько идентичных формулировок, чинятся разом)
  [
    'биопрепарат Фитоверм (менее токсичен, можно применять чаще, действует медленнее).',
    'биопрепарат Фитоверм (менее токсичен, можно применять чаще, действует медленнее; эффективнее в тепле — от +12°C, лучше при +18°C и выше).',
  ],
  [
    'биопрепарат Фитоверм (менее токсичен, можно применять чаще).',
    'биопрепарат Фитоверм (менее токсичен, можно применять чаще; эффективнее в тепле — от +12°C, лучше при +18°C и выше).',
  ],
  [
    'при слабом поражении — биопрепарат «Фитоверм».',
    'при слабом поражении — биопрепарат «Фитоверм» (эффективнее в тепле — от +12°C, лучше при +18°C и выше).',
  ],
  [
    'Инта-Вир или Фитоверм (от тли); обрабатывают в один день',
    'Инта-Вир или Фитоверм (от тли, эффективнее в тепле — от +12°C); обрабатывают в один день',
  ],
  [
    'биопрепарат «Фитоверм» (безопаснее для опылителей, обрабатывать до/после цветения, не во время).',
    'биопрепарат «Фитоверм» (безопаснее для опылителей, обрабатывать до/после цветения, не во время; эффективнее в тепле — от +12°C).',
  ],
  [
    'обработка «Фитовермом» сразу после сбора урожая.',
    'обработка «Фитовермом» (эффективнее в тепле — от +12°C) сразу после сбора урожая.',
  ],

  // Топаз (2 упоминания в одной строке) + коллоидная сера
  [
    '«Топаз» (от росы)',
    '«Топаз» (от росы, от +10°C, оптимум +10…+25°C)',
  ],
  [
    'мучнистой росы на клёне, барбарисе, спирее — тот же «Топаз» или коллоидная сера по инструкции.',
    'мучнистой росы на клёне, барбарисе, спирее — тот же «Топаз» или коллоидная сера (оптимум +20…+28°C, выше +30°C — ожог листьев) по инструкции.',
  ],

  // Скор + Хорус (яблоня/груша, парша)
  [
    'От парши на яблоне и груше — «Скор» или «Хорус» по инструкции, с соблюдением срока ожидания.',
    'От парши на яблоне и груше — «Скор» (оптимум +14…+25°C, ниже +12°C эффект резко падает) или «Хорус» (эффективен и в холод, от +3°C) по инструкции, с соблюдением срока ожидания.',
  ],
  // Хорус упомянут без температуры отдельно (искореняющее опрыскивание, апрель)
  [
    '3%-я бордоская жидкость (300 г медного купороса + 400 г извести на 10 л воды) или препарат «Хорус» (эффективен при более низких температурах, от +3°C).',
    '3%-я бордоская жидкость (+5…+25°C, 300 г медного купороса + 400 г извести на 10 л воды) или препарат «Хорус» (эффективен при более низких температурах, от +3°C).',
  ],

  // Лепидоцид/Битоксибациллин (август, капуста)
  [
    'От гусениц на капусте поздних сортов — биопрепарат «Лепидоцид» или «Битоксибациллин» (короткий срок ожидания).',
    'От гусениц на капусте поздних сортов — биопрепарат «Лепидоцид» или «Битоксибациллин» (оба малоэффективны ниже +13°C, оптимум +18…+30°C; короткий срок ожидания).',
  ],
];

let totalChanged = 0;
for (const [oldFrag, newFrag] of REPLACEMENTS) {
  let count = 0;
  for (const r of rows) {
    if (r.detail && r.detail.includes(oldFrag)) {
      r.detail = r.detail.split(oldFrag).join(newFrag);
      count++;
    }
  }
  if (count === 0) console.warn('НЕ НАЙДЕНО:', oldFrag.slice(0, 70));
  totalChanged += count;
}
console.log(`Правок применено (по всем регионам суммарно): ${totalChanged}`);

const ws = XLSX.utils.json_to_sheet(rows);
ws['!cols'] = [
  { wch: 16 }, { wch: 10 }, { wch: 10 }, { wch: 10 }, { wch: 10 },
  { wch: 24 }, { wch: 14 }, { wch: 60 }, { wch: 50 }, { wch: 40 },
];
wb.Sheets['Calendar'] = ws;
XLSX.writeFile(wb, XLSX_PATH);
